[{"order":1,"type":"heading","text":"Mastering Route Handlers and Request/Response Handling in Next.js"},{"order":2,"type":"paragraph","text":"Route Handlers in Next.js allow you to create custom request handlers for your application using the Web Request and Response APIs. Introduced in the App Router, they replace the legacy API Routes and offer seamless integration with modern serverless and edge environments."},{"order":3,"type":"subheading","text":"Creating a Basic Route Handler"},{"order":4,"type":"paragraph","text":"To create a Route Handler, you need to add a route.js or route.ts file inside the app directory. The file path dictates the endpoint URL. For example, placing a file at app/api/hello/route.js maps to the /api/hello endpoint."},{"order":5,"type":"code","text":"import { NextResponse } from 'next/server';

export async function GET(request) {
  return NextResponse.json({ message: 'Hello, Next.js!' });
}"},{"order":6,"type":"subheading","text":"Supported HTTP Methods"},{"order":7,"type":"paragraph","text":"Route Handlers natively support the standard HTTP methods. You simply export named functions corresponding to the method you want to handle:"},{"order":8,"type":"bullet_point","text":"GET: Retrieve data or resources."},{"order":9,"type":"bullet_point","text":"POST: Create new resources or submit data."},{"order":10,"type":"bullet_point","text":"PUT / PATCH: Update existing resources."},{"order":11,"type":"bullet_point","text":"DELETE: Remove resources."},{"order":12,"type":"subheading","text":"Handling Incoming Requests"},{"order":13,"type":"paragraph","text":"The first argument passed to a Route Handler is the NextRequest object, which is an extension of the standard Request API. It provides convenient methods for handling URL query parameters, cookies, and headers."},{"order":14,"type":"code","text":"import { NextResponse } from 'next/server';

export async function GET(request) {
  const url = new URL(request.url);
  const queryParam = url.searchParams.get('search');

  return NextResponse.json({ result: `You searched for: ${queryParam}` });
}"},{"order":15,"type":"subheading","text":"Reading JSON and Form Data"},{"order":16,"type":"paragraph","text":"For mutating requests like POST or PUT, you can extract the body payload by calling await request.json() or request.formData() depending on the content type."},{"order":17,"type":"code","text":"import { NextResponse } from 'next/server';

export async function POST(request) {
  try {
    const body = await request.json();
    const { name, email } = body;

    // Perform database operations here

    return NextResponse.json({ success: true, data: { name, email } }, { status: 201 });
  } catch (error) {
    return NextResponse.json({ success: false, error: 'Invalid JSON payload' }, { status: 400 });
  }
}"},{"order":18,"type":"subheading","text":"Dynamic Route Segments"},{"order":19,"type":"paragraph","text":"Just like page components, Route Handlers support dynamic segments. The second argument is a context object containing the params property."},{"order":20,"type":"code","text":"import { NextResponse } from 'next/server';

export async function GET(request, { params }) {
  const { id } = params;

  // Fetch resource by id
  return NextResponse.json({ itemId: id, name: 'Sample Item' });
}"},{"order":21,"type":"subheading","text":"Working with Response Headers and Cookies"},{"order":22,"type":"paragraph","text":"You can manipulate headers and cookies directly using the NextResponse helper or by returning a custom Response object."},{"order":23,"type":"code","text":"import { NextResponse } from 'next/server';

export async function GET(request) {
  const response = NextResponse.json({ status: 'Authenticated' });

  response.cookies.set({
    name: 'token',
    value: 'secret-token-value',
    httpOnly: true,
    path: '/',
  });

  response.headers.set('X-Custom-Header', 'my-custom-value');

  return response;
}"},{"order":24,"type":"subheading","text":"Conclusion"},{"order":25,"type":"paragraph","text":"Next.js Route Handlers provide a robust, standards-compliant way to build backend APIs directly within your full-stack application. By leveraging Web standard Request and Response interfaces, developers can write predictable, portable, and performant code."}]
